export const VUCUT_BOLGE_ETIKETLERI: Record<string, string> =
  Object.fromEntries(VUCUT_BOLGELERI.map((b) => [b.kod, b.ad]));

export const bolgeBul = (kod: string) => VUCUT_BOLGELERI.find((b) => b.kod === kod);

export const bolgeYolu = (cinsiyet: Cinsiyet, kod: string): string | undefined =>
  BOLGE_YOLLARI[cinsiyet]?.[kod];

/** Bir yuzun bolgeleri, path'leriyle birlikte */
export const yuzunBolgeleri = (cinsiyet: Cinsiyet, yuz: VucutYuzu) =>
  VUCUT_BOLGELERI.filter((b) => b.yuz === yuz).map((b) => ({
    ...b,
    d: BOLGE_YOLLARI[cinsiyet][b.kod],
  }));

export const figurGorseli = (cinsiyet: Cinsiyet, yuz: VucutYuzu) =>
  `/vucut/body-${cinsiyet}-${yuz}.webp`;

/** 0-10 siddet -> 3 renk bandi */
export function siddetBandi(siddet: number): 1 | 2 | 3 {
  if (siddet <= 3) return 1;
  if (siddet <= 6) return 2;
  return 3;
}

